Fresh public reads are required after the mutations to confirm that original top-level names are gone, each expected name appears in its assigned vacation directory, and every moved file retains its original name, content, and dates.

```python
remaining_root_files = apis.file_system.show_directory(access_token=file_system_access_token, directory_path=vacation_root, entry_type="files", recursive=False)
remaining_root_file_names = {entry.rstrip("/").rsplit("/", 1)[-1] for entry in remaining_root_files}
original_file_names = {item["original_file_name"] for item in move_plan}
assert original_file_names.isdisjoint(remaining_root_file_names)
expected_names_by_spot = {spot: {item["original_file_name"] for item in move_plan if item["vacation_spot"] == spot} for spot in ("Rome", "Santorini", "Berlin")}
observed_names_by_spot = {}
for spot in ("Rome", "Santorini", "Berlin"):
    destination_entries = apis.file_system.show_directory(access_token=file_system_access_token, directory_path=vacation_root + spot + "/", entry_type="files", recursive=False)
    observed_names_by_spot[spot] = {entry.rstrip("/").rsplit("/", 1)[-1] for entry in destination_entries}
    assert expected_names_by_spot[spot].issubset(observed_names_by_spot[spot])
moved_file_records = []
for planned_move in move_plan:
    moved_record = apis.file_system.show_file(file_path=planned_move["destination_file_path"], access_token=file_system_access_token)
    moved_file_records.append(moved_record)
    assert moved_record["path"].rstrip("/").rsplit("/", 1)[-1] == planned_move["original_file_name"]
    assert "/" + planned_move["vacation_spot"] + "/" in moved_record["path"].replace("\\", "/")
    assert moved_record["content"] == planned_move["expected_content"]
    assert moved_record["created_at"] == planned_move["expected_created_at"]
    assert moved_record["updated_at"] == planned_move["expected_updated_at"]
verification_summary = {"verified_file_count": len(moved_file_records), "remaining_original_top_level_count": len(original_file_names.intersection(remaining_root_file_names)), "planned_counts_by_spot": {spot: len(expected_names_by_spot[spot]) for spot in expected_names_by_spot}}
print(verification_summary)
